insert into public.reviews (id, vendor_id, reviewer_display_name, professionalism, punctuality, service_attitude, value_for_money, would_choose_again, review_text, is_public, is_seeded, created_at) values
  ('50000000-0000-4000-8000-000000100001', '30000000-0000-4000-8000-000000001001', 'Noa & Gil', 4, 4, 4, 3, true, 'We would have liked a little more detail in the first proposal, although the follow-up was helpful. The core service was solid and matched what we agreed.', true, true, '2024-03-03T10:00:00.000Z'),
  ('50000000-0000-4000-8000-000000100002', '30000000-0000-4000-8000-000000001001', 'Tamar & Dan', 4, 4, 4, 3, true, 'The schedule felt tight at first, then improved once we confirmed responsibilities. The core service was solid and matched what we agreed.', true, true, '2025-04-06T10:00:00.000Z'),
  ('50000000-0000-4000-8000-000000100003', '30000000-0000-4000-8000-000000001001', 'Bar & Lior', 4, 4, 4, 3, true, 'A small last-minute adjustment was needed, and the team handled it professionally. The core service was solid and matched what we agreed.', true, true, '2023-05-09T10:00:00.000Z'),
  ('50000000-0000-4000-8000-000000100004', '30000000-0000-4000-8000-000000001001', 'Shani & Itai', 4, 4, 4, 3, true, 'The package was not the cheapest option, but its inclusions were clear and useful. The core service was solid and matched what we agreed.', true, true, '2024-06-12T10:00:00.000Z'),
  ('50000000-0000-4000-8000-000000100005', '30000000-0000-4000-8000-000000001002', 'Shira & Tom', 4, 4, 4, 4, true, 'The in-house catering was thoughtfully handled and the team communicated clearly throughout. The schedule felt tight at first, then improved once we confirmed responsibilities.', true, true, '2025-05-04T10:00:00.000Z'),
